'use strict'
// ARGUS Owner Conversation Quality page — browser acceptance (Claude, 2026-11-10).
// Real Chromium on the real /crm/owner-quality page; /api/crm/* is answered by a
// stateful mock shaped like the production routes. The report body is a REAL
// report generated by services/ownerQualityReport.js on the isolated test DB
// (tests/fixtures/owner-quality-report.json). No WhatsApp, no production data.
//   CRM_BASE=http://localhost:3000 node --test tests/owner-quality.test.cjs
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const puppeteer = require('puppeteer')

const BASE = process.env.CRM_BASE || 'http://localhost:3000'
const OUT = path.join(__dirname, 'screenshots', 'owner-quality'); fs.mkdirSync(OUT, { recursive: true })
const FIX = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'owner-quality-report.json'), 'utf8'))

function store() {
  return {
    reports: [{ ...FIX, reviews: [] }], posts: [], generated: 0,
    incidents: [{ id: 7, created_at: '2026-11-10T09:41:00Z', severity: 'P0', kind: 'false_unavailable', session: 'kevthirdd', detail: 'facts engine marked a still-offered property as removed' }],
  }
}
const listOf = s => ({
  reports: s.reports.map(r => ({ id: r.id, created_at: r.created_at, trigger: r.trigger, period_from: r.period_from, period_to: r.period_to, digest: r.digest, severity_counts: r.report.severity_counts, release_decision: r.report.release_decision })),
  schedule: { next_run_at: '2026-11-16T07:30:00Z', last_run_at: null, cron: 'MON 08:30', timezone: 'Europe/Malta' },
  open_incidents: s.incidents,
})

async function mount(page, s) {
  await page.setRequestInterception(true)
  page.on('request', req => {
    const u = new URL(req.url()); if (!u.pathname.startsWith('/api/crm/')) return req.continue()
    const p = u.pathname.replace('/api/crm/', ''), m = req.method()
    const json = (body, status = 200) => req.respond({ status, contentType: 'application/json', body: JSON.stringify(body) })
    let mm
    if (p === 'me') return json({ agent: { id: 1, username: 'kevin', name: 'Kevin', role: 'admin' }, reveals: { used: 0, limit: 50 } })
    if (p === 'owner-quality/reports' && m === 'GET') return json(listOf(s))
    if (p === 'owner-quality/reports' && m === 'POST') {
      s.generated++
      const r = { ...FIX, id: `00000000-0000-4000-8000-00000000000${s.generated}`, created_at: new Date().toISOString(), digest: FIX.digest.replace(/^Owner AI: \d+/, 'Owner AI: 8'), reviews: [] }
      s.reports.unshift(r); return json({ ok: true, id: r.id, digest: r.digest })
    }
    if ((mm = /^owner-quality\/reports\/([^/]+)\/cases\/([^/]+)\/review$/.exec(p))) {
      const body = JSON.parse(req.postData() || '{}'); s.posts.push({ caseId: decodeURIComponent(mm[2]), ...body })
      const r = s.reports.find(x => x.id === mm[1]); r.reviews = [...r.reviews.filter(v => v.case_id !== decodeURIComponent(mm[2])), { case_id: decodeURIComponent(mm[2]), decision: body.decision, corrected_action: body.correctedAction, corrected_reply: body.correctedReply, note: body.note, reviewer: 'kevin', created_at: new Date().toISOString() }]
      return json({ id: s.posts.length, case_id: mm[2], decision: body.decision })
    }
    if ((mm = /^owner-quality\/reports\/([^/]+)$/.exec(p))) return json(s.reports.find(x => x.id === mm[1]))
    if ((mm = /^owner-quality\/conversations\/(\d+)$/.exec(p))) return json({ id: Number(mm[1]), session: 'default', status: 'active_collecting', reason: null, stored_facts: { price: 4500 },
      log: [{ from: 'owner', text: 'Good day we have a bungalow in Kappara 4 bedroom 3 bathrooms big pool', at: '2026-11-10T08:39:38Z' }, { from: 'bot', text: 'Great, noted, could you tell me the permit or licence status?', at: '2026-11-10T09:40:47Z' }], decisions: [] })
    if ((mm = /^owner-quality\/incidents\/(\d+)\/resolve$/.exec(p))) { s.incidents = s.incidents.filter(i => i.id !== Number(mm[1])); return json({ ok: true }) }
    return json({})
  })
}

for (const [width, height] of [[1440, 1000], [390, 844], [360, 740]]) {
  test(`owner quality page at ${width}px: report, KPIs, review drawer, golden, releases`, { timeout: 240000 }, async () => {
    const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox'] })
    try {
      const page = await browser.newPage()
      const s = store()
      await mount(page, s)
      await page.setViewport({ width, height, isMobile: width < 768, hasTouch: false })
      await page.evaluateOnNewDocument(() => { try { sessionStorage.setItem('argus_intro_seen', '1'); localStorage.setItem('crm_theme_pref', 'dark') } catch {} })
      await page.goto(`${BASE}/crm/owner-quality`, { waitUntil: 'networkidle2', timeout: 120000 })
      await page.waitForSelector('[data-testid="digest"]', { timeout: 60000 })
      const digest = await page.$eval('[data-testid="digest"]', e => e.textContent)
      assert.match(digest, /^Owner AI: 8 issues need review; 0 P0; 0 good examples preserved/)
      assert.match(await page.$eval('[data-testid="schedule"]', e => e.textContent), /Monday 08:30 Malta · next Mon 16 Nov, 08:30/)
      assert.match(await page.$eval('[data-testid="incidents"]', e => e.textContent), /1 open P0 incident/)
      assert.equal(await page.$eval('[data-testid="kpi-residential_permit_questions"] b', e => e.textContent), '1')
      assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1), 'no horizontal overflow (overview)')
      await page.screenshot({ path: path.join(OUT, `${width}-overview.png`), fullPage: false })

      // KPI → filtered Needs Review
      await page.click('[data-testid="kpi-residential_permit_questions"]')
      await page.waitForSelector('[data-testid^="case-C-"]')
      const visible = await page.$$eval('[data-testid^="case-C-"]', els => els.length)
      assert.equal(visible, 1, 'KPI opens only its cases')
      await page.screenshot({ path: path.join(OUT, `${width}-review.png`), fullPage: false })

      // Drawer: evidence + correction
      await page.click('[data-testid^="case-C-"]')
      await page.waitForSelector('[data-testid="case-drawer"]')
      const facts = await page.$eval('[data-testid="drawer-facts"]', e => e.textContent)
      for (const label of ['What the owner said', 'What was sent', 'What data was stored', 'Which rule failed', 'Correct action', 'Produced by']) assert.ok(facts.includes(label), label)
      const [evBtn] = await page.$$('xpath/.//button[contains(., "Open full evidence")]')
      await evBtn.click()
      await page.waitForSelector('[data-testid="evidence"]')
      await page.select('select[aria-label="Correct action"]', 'ACKNOWLEDGE_UPDATE')
      await page.type('textarea[aria-label="Correct reply"]', 'Thanks — noted as a residential bungalow.')
      await page.screenshot({ path: path.join(OUT, `${width}-drawer.png`), fullPage: false })
      await page.click('[data-testid="correct"]')
      await page.waitForSelector('[data-testid="toast"]')
      assert.match(await page.$eval('[data-testid="toast"]', e => e.textContent), /regression fixture candidate/)
      assert.equal(s.posts.length, 1)
      assert.deepEqual({ d: s.posts[0].decision, a: s.posts[0].correctedAction, r: s.posts[0].correctedReply }, { d: 'correct', a: 'ACKNOWLEDGE_UPDATE', r: 'Thanks — noted as a residential bungalow.' })
      await page.waitForFunction(() => /CORRECT/.test(document.querySelector('[data-testid^="case-C-"]')?.textContent || ''))

      // Golden + Releases tabs
      await page.click('[data-testid="tab-golden"]'); await page.waitForSelector('[data-testid="golden"]')
      assert.ok((await page.$eval('[data-testid="golden"]', e => e.textContent)).includes('BAD'))
      await page.click('[data-testid="tab-releases"]'); await page.waitForSelector('[data-testid="releases"]')
      assert.match(await page.$eval('[data-testid="releases"]', e => e.textContent), /owner-decision-2026-11-10\.1/)
      await page.screenshot({ path: path.join(OUT, `${width}-releases.png`), fullPage: false })

      // Export link + generate now + incident resolve
      assert.match(await page.$eval('[data-testid="export"]', e => e.getAttribute('href')), /^\/api\/crm\/owner-quality\/reports\/[^/]+\/export$/)
      await page.click('[data-testid="generate"]')
      await page.waitForFunction(() => /Owner AI: 8 issues/.test(document.querySelector('[data-testid="toast"]')?.textContent || ''))
      assert.equal(s.generated, 1)
      const [resolve] = await page.$$('xpath/.//button[contains(., "Mark resolved")]')
      await resolve.click()
      await page.waitForFunction(() => !document.querySelector('[data-testid="incidents"]'))
      assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1), 'no horizontal overflow (end)')
    } finally { await browser.close() }
  })
}
